module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] OUT,
    output reg OVERFLOW
);

    wire [3:0] twos_comp_B = (~B) + 1;

    always @* begin
        OUT <= A;
        OVERFLOW <= 0;
        if (SUBTRACT) begin
            OUT <= A + twos_comp_B;
        end else begin
            OUT <= A + B;
        end
        if (A >= OUT && SUBTRACT) begin
            OVERFLOW <= 1;
        end else if (A <= OUT && !SUBTRACT) begin
            OVERFLOW <= 1;
        end
    end
endmodule
