// Define the D flip-flop module
module dff_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    output reg [7:0] q
);

    always @(negedge clk) begin
        if (reset) begin
            q <= 8'b0;
        end else begin
            q <= d;
        end
    end

endmodule

// Define the any edge detection module
module anyedge_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    output reg [7:0] q
);

    reg [7:0] d_ff;

    always @(posedge clk) begin
        if (reset) begin
            d_ff <= 8'b0;
            q <= 8'b0;
        end else begin
            d_ff <= d;
            q <= d ^ d_ff;
        end
    end

endmodule

// Define the OR gate module
module or_gate_module (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] c
);

    always @(a or b) begin
        c <= a | b;
    end

endmodule
