    input clk,
    input reset,      // Asynchronous active-high reset
    output reg [3:0] q);

    reg [3:0] q1, q2, q3;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q1 <= 4'b0000;
            q2 <= 4'b0000;
            q3 <= 4'b0000;
            q <= 4'b0000;
