    input A,
    input B,
    input C_in,
    output [8:0] out
);

    wire [1:0] fa1_out;
    wire [1:0] fa2_out;
    wire parity_bit;

    // Full Adder 1
    full_adder fa1 (
        .A(A),
        .B(B),
        .C_in(C_in),
        .sum(fa1_out[0]),
        .C_out(fa1_out[1])
    );

