module full_adder(
    input a,
    input b,
    input cin,
    output s,
    output cout
);

    wire sum1, sum2, sum3;

    // XOR gates to calculate sum
    assign sum1 = a ^ b;
    assign s = sum1 ^ cin;

    // AND gates to calculate carry out
    assign sum2 = a & b;
    assign sum3 = cin & sum1;
    assign cout = sum2 | sum3;

endmodule
