			4'd12: out <= ~(a | b);				
			4'd1:  out <= a | b;				
			4'd7:  out <= {{31{1'b0}}, slt};	
			4'd6:  out <= sub_ab;				
			4'd13: out <= a ^ b;				
			default: out <= 0;
		endcase
	end

endmodule

`endif

